const input = $input.first().json;
const markdown = input.body?.markdown || input.body?.content || JSON.stringify(input.body);
const agentType = input.body?.agent || 'unknown';
const title = input.body?.title || 'Agent Output';
const theme = input.body?.theme || 'modern-minimalist';

const sections = [];
const lines = markdown.split('\n');
let currentSection = { type: 'narrative', heading: '', content: '', lines: [] };
let tableCount = 0;
let metricCount = 0;
let hasTimeline = false;
let hasBulletLists = false;

for (const line of lines) {
  if (line.includes('|') && line.trim().startsWith('|')) {
    if (currentSection.type !== 'table') {
      if (currentSection.content) sections.push({...currentSection});
      currentSection = { type: 'table', heading: currentSection.heading, content: '', lines: [] };
    }
    currentSection.lines.push(line);
    currentSection.content += line + '\n';
    tableCount++;
    continue;
  }
  if (/\$[\d,.]+[BMK]?|[\d.]+%|[\d.]+x\b/.test(line) && line.length < 200) {
    metricCount++;
  }
  if (line.startsWith('#')) {
    if (currentSection.content) sections.push({...currentSection});
    const level = line.match(/^#+/)[0].length;
    currentSection = { type: 'narrative', heading: line.replace(/^#+\\s*/, ''), level, content: '', lines: [] };
    continue;
  }
  if (/\b(20[2-3]\d|Q[1-4]|January|February|March|April|May|June|July|August|September|October|November|December)\b/.test(line)) {
    hasTimeline = true;
  }
  if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
    hasBulletLists = true;
  }
  currentSection.content += line + '\n';
  currentSection.lines.push(line);
}
if (currentSection.content) sections.push(currentSection);

let layoutType = 'article';
if (tableCount > 10) layoutType = 'data-heavy-dashboard';
else if (tableCount > 3) layoutType = 'dashboard';
else if (metricCount > 5) layoutType = 'metrics-dashboard';
else if (hasTimeline && tableCount > 1) layoutType = 'report-dashboard';

const components = [];
for (const section of sections) {
  if (section.type === 'table') {
    components.push({ type: 'data-table', heading: section.heading, sortable: true });
  } else if (section.heading && metricCount > 0) {
    components.push({ type: 'section-card', heading: section.heading });
  }
}

return [{
  json: {
    markdown, agentType, title, theme,
    classification: { layoutType, tableCount, metricCount, hasTimeline, hasBulletLists, sectionCount: sections.length, components },
    sections
  }
}];

const data = $input.first().json;
const { markdown, title, theme, classification, sections, agentType } = data;

const themes = {
  'tech-innovation': {
    bg: '#0f172a', surface: '#1e293b', surfaceAlt: '#334155',
    text: '#f8fafc', textMuted: '#94a3b8', accent: '#f97316',
    accentBg: '#f97316', success: '#22c55e', warning: '#f59e0b',
    error: '#ef4444', border: '#475569',
    font: "'Space Grotesk', sans-serif", bodyFont: "'DM Sans', sans-serif"
  },
  'modern-minimalist': {
    bg: '#ffffff', surface: '#f8fafc', surfaceAlt: '#f1f5f9',
    text: '#0f172a', textMuted: '#64748b', accent: '#0ea5e9',
    accentBg: '#0ea5e9', success: '#22c55e', warning: '#f59e0b',
    error: '#ef4444', border: '#e2e8f0',
    font: "'Outfit', sans-serif", bodyFont: "'Plus Jakarta Sans', sans-serif"
  },
  'midnight-galaxy': {
    bg: '#0c0a1d', surface: '#1a1533', surfaceAlt: '#2d2650',
    text: '#e8e4f0', textMuted: '#9b8fc4', accent: '#a78bfa',
    accentBg: '#7c3aed', success: '#34d399', warning: '#fbbf24',
    error: '#f87171', border: '#3b3366',
    font: "'Sora', sans-serif", bodyFont: "'Manrope', sans-serif"
  }
};

const t = themes[theme] || themes['modern-minimalist'];

function parseTable(tableLines) {
  const rows = tableLines.filter(l => l.trim().startsWith('|') && !l.includes('---'));
  if (rows.length < 1) return '';
  const parseRow = (row) => row.split('|').filter(c => c.trim()).map(c => c.trim());
  const headers = parseRow(rows[0]);
  const dataRows = rows.slice(1).map(parseRow);
  let html = `<div style=\"overflow-x:auto;border-radius:8px;border:1px solid ${t.border}\">`;
  html += '<table style=\"width:100%;border-collapse:collapse;font-size:14px\">';
  html += '<thead><tr>';
  headers.forEach(h => {
    html += `<th style=\"padding:12px 16px;text-align:left;font-weight:600;background:${t.surfaceAlt};color:${t.text};border-bottom:2px solid ${t.border}\">${h}</th>`;
  });
  html += '</tr></thead><tbody>';
  dataRows.forEach((row, i) => {
    const bg = i % 2 === 0 ? t.surface : t.bg;
    html += '<tr>';
    row.forEach(cell => {
      let style = `padding:10px 16px;border-bottom:1px solid ${t.border};color:${t.text};background:${bg}`;
      if (/^\\+/.test(cell) || /positive|strong|low risk/i.test(cell)) style += `;color:${t.success}`;
      if (/^-[\\d]/.test(cell) || /negative|weak|high risk/i.test(cell)) style += `;color:${t.error}`;
      html += `<td style=\"${style}\">${cell}</td>`;
    });
    html += '</tr>';
  });
  html += '</tbody></table></div>';
  return html;
}

function renderSection(section) {
  if (section.type === 'table') {
    return `<div style=\"margin:16px 0\">${section.heading ? `<h3 style=\"font-size:16px;font-weight:600;margin-bottom:8px;color:${t.text}\">${section.heading}</h3>` : ''}${parseTable(section.lines)}</div>`;
  }
  let content = section.content
    .replace(/\\*\\*(.+?)\\*\\*/g, `<strong style=\"color:${t.text}\">$1</strong>`)
    .replace(/^- (.+)$/gm, `<li style=\"margin:4px 0;color:${t.textMuted}\">$1</li>`)
    .replace(/^\\* (.+)$/gm, `<li style=\"margin:4px 0;color:${t.textMuted}\">$1</li>`)
    .replace(/(<li[^>]*>.*<\\/li>\\n?)+/g, (match) => `<ul style=\"padding-left:20px;margin:8px 0\">${match}</ul>`)
    .replace(/\\[([^\\]]+)\\]\\(([^)]+)\\)/g, `<a href=\"$2\" style=\"color:${t.accent};text-decoration:underline\" target=\"_blank\">$1</a>`)
    .replace(/\\n\\n/g, '</p><p style=\"margin:8px 0;line-height:1.6\">')
    .replace(/\\n/g, '<br>');
  const headingHtml = section.heading ?
    `<h${section.level || 2} style=\"font-size:${section.level === 1 ? 24 : section.level === 2 ? 20 : 16}px;font-weight:600;margin:24px 0 12px 0;color:${t.text};font-family:${t.font}\">${section.heading}</h${section.level || 2}>` : '';
  return `<div style=\"margin:12px 0\">${headingHtml}<div style=\"color:${t.textMuted};line-height:1.6;font-size:14px\"><p style=\"margin:8px 0\">${content}</p></div></div>`;
}

const timestamp = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'full', timeStyle: 'short' });

const html = `<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>${title}</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=DM+Sans:wght@400;500;600&family=Outfit:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600&family=Sora:wght@400;500;600;700&family=Manrope:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  body { background: ${t.bg}; color: ${t.text}; font-family: ${t.bodyFont}; }\n  .container { max-width: 1200px; margin: 0 auto; padding: 32px 24px; }\n  .header { margin-bottom: 32px; padding-bottom: 24px; border-bottom: 2px solid ${t.border}; }\n  .header h1 { font-family: ${t.font}; font-size: 28px; font-weight: 700; margin-bottom: 8px; }\n  .header .meta { font-size: 13px; color: ${t.textMuted}; }\n  .header .meta .agent-badge { display: inline-block; padding: 2px 10px; border-radius: 12px; background: ${t.accentBg}; color: #fff; font-size: 11px; font-weight: 600; margin-left: 8px; text-transform: uppercase; }\n  .stats-bar { display: flex; gap: 16px; margin: 20px 0; flex-wrap: wrap; }\n  .stat-chip { padding: 8px 16px; border-radius: 8px; background: ${t.surface}; border: 1px solid ${t.border}; font-size: 13px; }\n  .stat-chip .label { color: ${t.textMuted}; }\n  .stat-chip .value { font-weight: 600; color: ${t.accent}; margin-left: 4px; }\n  .content { display: grid; gap: 24px; }\n  .section-card { background: ${t.surface}; border: 1px solid ${t.border}; border-radius: 12px; padding: 24px; }\n  @media (max-width: 768px) { .container { padding: 16px; } .stats-bar { flex-direction: column; } }\n  @media print { body { background: #fff; color: #000; } .section-card { border: 1px solid #ddd; } }\n</style>\n</head>\n<body>\n<div class=\"container\">\n  <div class=\"header\">\n    <h1>${title}</h1>\n    <div class=\"meta\">\n      ${timestamp}\n      <span class=\"agent-badge\">${agentType}</span>\n    </div>\n  </div>\n  <div class=\"stats-bar\">\n    <div class=\"stat-chip\"><span class=\"label\">Layout:</span><span class=\"value\">${classification.layoutType}</span></div>\n    <div class=\"stat-chip\"><span class=\"label\">Tables:</span><span class=\"value\">${classification.tableCount}</span></div>\n    <div class=\"stat-chip\"><span class=\"label\">Sections:</span><span class=\"value\">${classification.sectionCount}</span></div>\n    <div class=\"stat-chip\"><span class=\"label\">Metrics:</span><span class=\"value\">${classification.metricCount}</span></div>\n  </div>\n  <div class=\"content\">\n    ${sections.map(s => `<div class=\"section-card\">${renderSection(s)}</div>`).join('\\n')}\n  </div>\n</div>\n</body>\n</html>`;

return [{ json: { html, title, classification }, binary: {} }];

const data = $input.first().json;
const fs = require('fs');
const path = require('path');

const outputDir = '/home/node/output';
try { fs.mkdirSync(outputDir, { recursive: true }); } catch(e) {}

const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
const safeTitle = (data.title || 'output').replace(/[^a-zA-Z0-9-_]/g, '_').slice(0, 50);
const filename = `${safeTitle}_${timestamp}.html`;
const filepath = path.join(outputDir, filename);

fs.writeFileSync(filepath, data.html, 'utf8');

return [{ json: { saved: true, filepath, filename, size: data.html.length } }];
